//! A dimension's references: `{id, face, point?}` as a dimension keeps them (the element by GUID),
//! read from a command as serde reads the original's `Reference` (a map or a sequence), or given as
//! a point on a line or `{endpoint}`, and named in messages.

use super::super::common::*;
use crate::json::{Num, Value};
use crate::project::Project;

/// What of an element a reference measures to.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum Face {
    Centre,
    Left,
    Right,
    Start,
    End,
}

impl Face {
    pub fn word(self) -> &'static str {
        match self {
            Face::Centre => "centre",
            Face::Left => "left",
            Face::Right => "right",
            Face::Start => "start",
            Face::End => "end",
        }
    }
    pub fn parse(s: &str) -> Option<Face> {
        Some(match s {
            "centre" | "center" => Face::Centre,
            "left" => Face::Left,
            "right" => Face::Right,
            "start" => Face::Start,
            "end" => Face::End,
            _ => return None,
        })
    }
}

/// An end of a line.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum End {
    Start,
    End,
}

impl End {
    pub fn word(self) -> &'static str {
        match self {
            End::Start => "start",
            End::End => "end",
        }
    }
    pub fn parse(s: &str) -> Option<End> {
        match s {
            "start" => Some(End::Start),
            "end" => Some(End::End),
            _ => None,
        }
    }
}

/// The element a reference names: by GUID as kept, or an id or GUID the project hasn't (only while
/// a command checks what it was given).
#[derive(Clone, Debug, PartialEq)]
pub enum Target {
    Guid(String),
    /// Not in the project: how the command named it (an id, or a GUID).
    Missing(String),
}

#[derive(Clone, Debug, PartialEq)]
pub struct Ref {
    pub target: Target,
    pub face: Face,
    pub point: Option<End>,
}

impl Ref {
    pub fn guid(&self) -> &str {
        match &self.target {
            Target::Guid(g) => g,
            Target::Missing(s) => s,
        }
    }
    /// The element's id, if the project has it.
    pub fn id(&self, pr: &Project) -> Option<u64> {
        match &self.target {
            Target::Guid(g) => pr.find_guid(g),
            Target::Missing(_) => None,
        }
    }
    /// The same reference: the same element, face and end.
    pub fn same(&self, o: &Ref) -> bool {
        self.target == o.target && self.face == o.face && self.point == o.point
    }
    /// As a dimension keeps it: `{id, face, point?}`.
    pub fn to_value(&self) -> Value {
        let mut v = jobj! {"id" => self.guid(), "face" => self.face.word()};
        if let Some(p) = self.point {
            v.set("point", Value::s(p.word()));
        }
        v
    }
    /// As a dimension keeps it.
    pub fn from_value(v: &Value) -> Option<Ref> {
        let id = s_of(v, "id")?.to_string();
        let face = s_of(v, "face").and_then(Face::parse).unwrap_or(Face::Centre);
        let point = s_of(v, "point").and_then(End::parse);
        Some(Ref { target: Target::Guid(id), face, point })
    }
}

/// A dimension's references as it keeps them.
pub fn refs_of(e: &Value) -> Vec<Ref> {
    e.get("refs").and_then(|r| r.as_arr()).map(|a| a.iter().filter_map(Ref::from_value).collect()).unwrap_or_default()
}

/// What a command's `refs` holds, one by one: a reference, a point on a line, or `{endpoint}`.
pub enum RefIn {
    Ref { id: IdIn, face: Face, point: Option<End> },
    Point(P),
    Endpoint(P),
}

pub type P = [f64; 2];

/// An element named by id or GUID.
pub enum IdIn {
    Id(u64),
    Guid(String),
}

/// The element an id or GUID names: kept by its GUID, or missing.
pub fn target_of(pr: &Project, id: &IdIn) -> Target {
    match id {
        IdIn::Id(n) => match pr.guid_of(*n) {
            Some(g) if pr.elements.contains_key(n) => Target::Guid(g),
            _ => Target::Missing(n.to_string()),
        },
        IdIn::Guid(g) => match pr.find_guid(g) {
            Some(_) => Target::Guid(g.clone()),
            None => Target::Missing(g.clone()),
        },
    }
}

/// serde's words for what it got.
fn unexpected(v: &Value) -> String {
    v.kind_name()
}

/// Reads `refs[i]` as the original reads it; the error is the reason only.
pub fn parse_ref_in(v: &Value) -> Result<RefIn, String> {
    if let Some(a) = v.as_arr() {
        if a.len() == 2 {
            if let Some(p) = point_of(v) {
                return Ok(RefIn::Point(p));
            }
        }
    }
    if let Value::Obj(m) = v {
        if m.len() == 1 && m.contains("endpoint") {
            let x = m.get("endpoint").unwrap();
            return match point_of(x) {
                Some(p) => Ok(RefIn::Endpoint(p)),
                None => Err(format!("`endpoint` is a point [x, y], not {}", x.clone().sorted().to_compact())),
            };
        }
    }
    parse_reference(v)
        .map(|(id, face, point)| RefIn::Ref { id, face, point })
        .map_err(|e| format!("{} is not a reference {{id, face?}} or a point [x, y]: {}", v.clone().sorted().to_compact(), e))
}

/// serde's `Reference {id, face, point}`, from a map (fields in sorted order, unknown ones refused)
/// or a sequence.
fn parse_reference(v: &Value) -> Result<(IdIn, Face, Option<End>), String> {
    match v {
        Value::Obj(m) => {
            let mut keys: Vec<&String> = m.items.iter().map(|(k, _)| k).collect();
            keys.sort();
            let mut id = None;
            let mut face = Face::Centre;
            let mut point = None;
            for k in keys {
                let x = m.get(k).unwrap();
                match k.as_str() {
                    "id" => id = Some(parse_id(x)?),
                    "face" => face = parse_face(x)?,
                    "point" => point = parse_point(x)?,
                    _ => return Err(format!("unknown field `{}`, expected one of `id`, `face`, `point`", k)),
                }
            }
            match id {
                Some(id) => Ok((id, face, point)),
                None => Err("missing field `id`".into()),
            }
        }
        Value::Arr(a) => {
            if a.is_empty() {
                return Err("invalid length 0, expected struct Reference with 3 elements".into());
            }
            if a.len() > 3 {
                return Err(format!("invalid length {}, expected fewer elements in array", a.len()));
            }
            let id = parse_id(&a[0])?;
            let face = match a.get(1) {
                Some(x) => parse_face(x)?,
                None => Face::Centre,
            };
            let point = match a.get(2) {
                Some(x) => parse_point(x)?,
                None => None,
            };
            Ok((id, face, point))
        }
        other => Err(format!("invalid type: {}, expected struct Reference", unexpected(other))),
    }
}

/// An element's GUID, or its id (a whole number, or one in a string).
pub fn parse_id(v: &Value) -> Result<IdIn, String> {
    match v {
        Value::Num(n) => {
            let f = n.as_f64();
            match n {
                Num::U(u) => Ok(IdIn::Id(*u)),
                Num::I(i) => Err(format!("{} is not an element id", i)),
                Num::F(_) => {
                    if f >= 0.0 && f.fract() == 0.0 && f < 1.8e19 {
                        Ok(IdIn::Id(f as u64))
                    } else {
                        Err(format!("{} is not an element id", f))
                    }
                }
            }
        }
        Value::Str(s) => {
            let t = s.trim();
            if let Ok(id) = t.parse::<u64>() {
                return Ok(IdIn::Id(id));
            }
            match crate::model::normalize_guid(t) {
                Some(g) => Ok(IdIn::Guid(g)),
                None => Err(format!("`{}` is not a GUID (xxxxxxxx-xxxx-xxxx-xxxx-xxxxxxxxxxxx) or an id", s)),
            }
        }
        other => Err(format!("invalid type: {}, expected an element's GUID, or its id", unexpected(other))),
    }
}

/// A unit variant of an enum as serde reads one: its name, or a map of it to null.
fn variant<'a>(v: &'a Value, names: &[&str], expected: &str) -> Result<&'a str, String> {
    let unknown = |s: &str| format!("unknown variant `{}`, expected {}", s, expected);
    match v {
        Value::Str(s) => {
            if names.contains(&s.as_str()) {
                Ok(s.as_str())
            } else {
                Err(unknown(s))
            }
        }
        Value::Obj(m) => {
            if m.items.len() != 1 {
                return Err("invalid value: map, expected map with a single key".into());
            }
            let (k, x) = &m.items[0];
            if !names.contains(&k.as_str()) {
                return Err(unknown(k));
            }
            match x {
                Value::Null => Ok(k.as_str()),
                other => Err(format!("invalid type: {}, expected unit", unexpected(other))),
            }
        }
        other => Err(format!("invalid type: {}, expected string or map", unexpected(other))),
    }
}

fn parse_face(v: &Value) -> Result<Face, String> {
    let names = ["center", "centre", "left", "right", "start", "end"];
    let s = variant(v, &names, "one of `center`, `centre`, `left`, `right`, `start`, `end`")?;
    Ok(Face::parse(s).unwrap())
}

fn parse_point(v: &Value) -> Result<Option<End>, String> {
    if v.is_null() {
        return Ok(None);
    }
    let s = variant(v, &["start", "end"], "`start` or `end`")?;
    Ok(End::parse(s))
}

// ---------------------------------------------------------------- names in messages

/// How a message names the element a reference is to by id: "wall 100002", "line 100003".
pub fn named(pr: &Project, r: &Ref) -> String {
    match r.id(pr) {
        Some(id) => format!("{} {}", cat_of(pr, id), id),
        None => format!("element {}", r.guid()),
    }
}

/// How a message names it by GUID: "door 5451…", "detail line 8c35…".
pub fn named_guid(pr: &Project, r: &Ref) -> String {
    let c = match r.id(pr) {
        Some(id) => cat_of(pr, id),
        None => String::new(),
    };
    format!("{} {}", category_words(&c), r.guid())
}

/// A category as the messages that name an element by GUID say it.
pub fn category_words(c: &str) -> String {
    match c {
        "line" => "detail line".to_string(),
        x => x.to_string(),
    }
}

/// What of its element a reference is to: "centre line", "left face", "start", "end of its start".
pub fn what(r: &Ref) -> String {
    let f = match r.face {
        Face::Centre => "centre line",
        Face::Left => "left face",
        Face::Right => "right face",
        Face::Start => "start",
        Face::End => "end",
    };
    match r.point {
        None => f.to_string(),
        Some(p) => format!("{} of its {}", p.word(), f),
    }
}

//! What a dimension measures: its references laid along the way it runs (an aligned or linear
//! one's stations), the angle between two lines, a radius, a diameter or an arc's length; and the
//! model's rules for it, in the order the original checks them.

use super::geom::{self, *};
use super::refs::{self, End, Face, Ref, Target};
use super::super::common::*;
use crate::json::Value;
use crate::project::Project;

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum Kind {
    Aligned,
    Linear,
    Angular,
    Radial,
    Diameter,
    ArcLength,
}

impl Kind {
    pub fn parse(s: &str) -> Option<Kind> {
        Some(match s {
            "aligned" => Kind::Aligned,
            "linear" => Kind::Linear,
            "angular" => Kind::Angular,
            "radial" => Kind::Radial,
            "diameter" => Kind::Diameter,
            "arc_length" => Kind::ArcLength,
            _ => return None,
        })
    }
    pub fn word(self) -> &'static str {
        match self {
            Kind::Aligned => "aligned",
            Kind::Linear => "linear",
            Kind::Angular => "angular",
            Kind::Radial => "radial",
            Kind::Diameter => "diameter",
            Kind::ArcLength => "arc_length",
        }
    }
    /// As the original's messages name it (its Debug).
    pub fn name(self) -> &'static str {
        match self {
            Kind::Aligned => "Aligned",
            Kind::Linear => "Linear",
            Kind::Angular => "Angular",
            Kind::Radial => "Radial",
            Kind::Diameter => "Diameter",
            Kind::ArcLength => "ArcLength",
        }
    }
    /// Whether it lays its references along a line (aligned or linear).
    pub fn along(self) -> bool {
        matches!(self, Kind::Aligned | Kind::Linear)
    }
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum Orient {
    Horizontal,
    Vertical,
}

impl Orient {
    pub fn parse(s: &str) -> Option<Orient> {
        match s {
            "horizontal" => Some(Orient::Horizontal),
            "vertical" => Some(Orient::Vertical),
            _ => None,
        }
    }
    pub fn word(self) -> &'static str {
        match self {
            Orient::Horizontal => "horizontal",
            Orient::Vertical => "vertical",
        }
    }
    /// The way a dimension of it measures.
    pub fn axis(self) -> P {
        match self {
            Orient::Horizontal => [1.0, 0.0],
            Orient::Vertical => [0.0, 1.0],
        }
    }
}

/// A dimension as the checks and the measuring read it.
#[derive(Clone, Debug)]
pub struct Dim {
    pub id: u64,
    pub kind: Kind,
    pub orient: Option<Orient>,
    pub refs: Vec<Ref>,
    pub at: P,
}

impl Dim {
    pub fn from_element(id: u64, e: &Value) -> Dim {
        Dim {
            id,
            kind: s_of(e, "kind").and_then(Kind::parse).unwrap_or(Kind::Aligned),
            orient: s_of(e, "orient").and_then(Orient::parse),
            refs: refs::refs_of(e),
            at: pt_of(e, "at").unwrap_or([0.0, 0.0]),
        }
    }
}

/// The walls joined, worked out once for all the dimensions a check or a command measures.
pub struct Ctx<'a> {
    pub pr: &'a Project,
    walls: std::cell::OnceCell<Vec<Wall>>,
}

impl<'a> Ctx<'a> {
    pub fn new(pr: &'a Project) -> Ctx<'a> {
        Ctx { pr, walls: std::cell::OnceCell::new() }
    }
    pub fn walls(&self) -> &Vec<Wall> {
        self.walls.get_or_init(|| geom::walls(self.pr))
    }
    pub fn wall(&self, id: u64) -> Option<&Wall> {
        self.walls().iter().find(|w| w.id() == id)
    }
}

/// What a reference is, in plan, for a dimension laying its references along a line.
#[derive(Clone, Copy, Debug)]
pub enum Geo {
    /// A line (its two ends, the way it runs from the first).
    Line(P, P),
    Point(P),
}

/// The line or point a reference of an aligned, linear or angular dimension is to, else why not.
pub fn ref_geo(cx: &Ctx, r: &Ref) -> Result<Geo, String> {
    let pr = cx.pr;
    let Some(id) = r.id(pr) else {
        return Err(format!("element {} doesn't exist", r.guid()));
    };
    let e = pr.el(id).unwrap();
    let c = cat(e);
    let g = || refs::named_guid(pr, r);
    let pick = |l: (P, P)| -> Geo {
        match r.point {
            None => Geo::Line(l.0, l.1),
            Some(End::Start) => Geo::Point(l.0),
            Some(End::End) => Geo::Point(l.1),
        }
    };
    match c {
        "wall" => {
            let w = cx.wall(id).ok_or_else(|| format!("element {} doesn't exist", r.guid()))?;
            let curved = !w.b.straight();
            match r.face {
                Face::Centre | Face::Left | Face::Right => {
                    if curved && r.point.is_none() {
                        return Err(format!("{}'s faces are arcs; measure to its start or its end, or its radius", g()));
                    }
                    let l = match r.face {
                        Face::Centre => (w.b.cl.start, w.b.cl.end),
                        Face::Left => w.left,
                        _ => w.right,
                    };
                    Ok(pick(l))
                }
                Face::Start => Ok(pick(w.sface)),
                Face::End => Ok(pick(w.eface)),
            }
        }
        "door" | "window" => {
            if matches!(r.face, Face::Left | Face::Right) {
                return Err(format!("{} has a centre and two jambs, start and end; measure to one of those", g()));
            }
            let (_, ls) = geom::opening_lines(pr, id).ok_or_else(|| format!("{} has a centre and two jambs, start and end; measure to one of those", g()))?;
            let l = match r.face {
                Face::Start => ls[1],
                Face::End => ls[2],
                _ => ls[0],
            };
            Ok(pick(l))
        }
        "grid" => {
            if r.face != Face::Centre {
                return Err(format!("{} has no faces; measure to its line", g()));
            }
            let a = pt_of(e, "start").unwrap_or([0.0, 0.0]);
            let b = pt_of(e, "end").unwrap_or([0.0, 0.0]);
            Ok(pick((a, b)))
        }
        "line" => {
            if matches!(r.face, Face::Left | Face::Right) {
                return Err(format!("{} has a line and two ends; measure to one of those", g()));
            }
            let Some(shape) = geom::line_shape(e) else {
                return Err(format!("{} has a line and two ends; measure to one of those", g()));
            };
            if r.face == Face::Centre && r.point.is_some() {
                let (a, b) = shape.ends();
                return Ok(Geo::Point(if r.point == Some(End::Start) { a } else { b }));
            }
            let LineShape::Line(a, b) = shape else {
                return Err(format!("{} is a {}; dimensions measure to straight ones (and radial ones to circles and arcs)", g(), shape.word()));
            };
            match r.face {
                Face::Centre => Ok(pick((a, b))),
                _ => {
                    // the line square to it at that end, from its right to its left
                    let d = unit(sub(b, a));
                    let n = left_of(d);
                    let p = if r.face == Face::Start { a } else { b };
                    Ok(pick((sub(p, n), add(p, n))))
                }
            }
        }
        _ => Err(format!("{} isn't a wall, a door, a window, a grid or a detail line", g())),
    }
}

/// How messages name the element of a reference: "wall 100002".
fn nm(pr: &Project, r: &Ref) -> String {
    refs::named(pr, r)
}

/// A dimension laid along a line: the way it runs, and each reference's station along it.
#[derive(Clone, Debug)]
pub struct Laid {
    /// The way it measures (east or north), a unit vector.
    pub dir: P,
    /// (station, the reference's index), in order along `dir`.
    pub stations: Vec<(f64, usize)>,
}

impl Laid {
    pub fn values(&self) -> Vec<f64> {
        self.stations.windows(2).map(|w| w[1].0 - w[0].0).collect()
    }
}

/// A unit vector made to point east (or north, where it points neither east nor west).
pub fn eastward(d: P) -> P {
    if d[0] > 1e-9 || (d[0].abs() <= 1e-9 && d[1] >= 0.0) {
        d
    } else {
        [-d[0], -d[1]]
    }
}

/// The count of references each kind takes, and what it says otherwise.
fn count_rule(d: &Dim) -> Result<(), String> {
    let n = d.refs.len();
    let ok = match d.kind {
        Kind::Aligned | Kind::Linear => (2..=10000).contains(&n),
        Kind::Angular => n == 2,
        Kind::Radial | Kind::Diameter => n == 1,
        Kind::ArcLength => n == 1 || n == 3,
    };
    if ok {
        return Ok(());
    }
    Err(match d.kind {
        Kind::Aligned | Kind::Linear => "a dimension measures between 2 to 10000 references".into(),
        Kind::Angular => "an angular dimension measures between two lines".into(),
        Kind::Radial => "a radial dimension measures one round element".into(),
        Kind::Diameter => "a diameter dimension measures one round element".into(),
        Kind::ArcLength => "an arc length dimension measures along one arc, all of it or between two points on it".into(),
    })
}

/// The rules a dimension holds to, after its type's, and what it measures: its values (the
/// segments, an angle in degrees, a radius, a diameter or a length), unrounded. The error is the
/// reason only (the caller says which dimension).
pub fn measure(cx: &Ctx, d: &Dim) -> Result<Vec<f64>, String> {
    count_rule(d)?;
    if d.orient.is_some() && d.kind != Kind::Linear {
        return Err(format!("only a linear dimension has an `orient`; this one is {}", d.kind.name()));
    }
    match d.kind {
        Kind::Aligned | Kind::Linear => Ok(lay(cx, d)?.values()),
        Kind::Angular => Ok(vec![angle(cx, d)?]),
        Kind::Radial | Kind::Diameter => {
            let r = radius(cx, d)?;
            Ok(vec![if d.kind == Kind::Diameter { 2.0 * r } else { r }])
        }
        Kind::ArcLength => Ok(vec![arc_length(cx, d)?]),
    }
}

/// An aligned or linear dimension's references laid along the way it measures.
pub fn lay(cx: &Ctx, d: &Dim) -> Result<Laid, String> {
    let pr = cx.pr;
    let mut geos: Vec<Geo> = Vec::new();
    let mut first: Option<(usize, P)> = None;
    for (i, r) in d.refs.iter().enumerate() {
        let g = ref_geo(cx, r)?;
        if d.refs[..i].iter().any(|o| o.same(r)) {
            return Err(format!("it measures to {}'s {} twice", nm(pr, r), refs::what(r)));
        }
        if let Geo::Line(a, b) = g {
            let u = unit(sub(b, a));
            if d.kind == Kind::Linear {
                let o = d.orient.unwrap_or(Orient::Horizontal);
                // its lines run square to the way it measures
                if cross(u, left_of(o.axis())).abs() > PARALLEL {
                    return Err(format!(
                        "{} isn't square to a {} dimension; measure to its ends, or make the dimension aligned",
                        nm(pr, r),
                        o.word()
                    ));
                }
            } else {
                match first {
                    None => first = Some((i, u)),
                    Some((k, f)) => {
                        if cross(u, f).abs() > PARALLEL {
                            return Err(format!(
                                "{} isn't parallel to {}; a dimension measures between parallel walls and grids",
                                nm(pr, r),
                                nm(pr, &d.refs[k])
                            ));
                        }
                    }
                }
            }
        }
        geos.push(g);
    }
    let dir = match (d.kind, first) {
        (Kind::Linear, _) => d.orient.unwrap_or(Orient::Horizontal).axis(),
        (_, Some((_, u))) => eastward(left_of(u)),
        (_, None) => {
            let pts: Vec<P> = geos.iter().map(|g| if let Geo::Point(p) = g { *p } else { [0.0, 0.0] }).collect();
            let p0 = pts[0];
            match pts.iter().skip(1).find(|p| dist(**p, p0) > 1e-9) {
                Some(p) => eastward(unit(sub(*p, p0))),
                None => return Err("its points are all in one place, so it has no way to run".into()),
            }
        }
    };
    let at = d.at;
    let mut st: Vec<(f64, usize)> = geos
        .iter()
        .enumerate()
        .map(|(i, g)| {
            let s = match g {
                Geo::Point(p) => dot(*p, dir),
                Geo::Line(a, b) => {
                    // where the dimension's line, through `at` along the way it measures, crosses it
                    let u = sub(*b, *a);
                    let den = cross(dir, u);
                    if den.abs() < 1e-12 {
                        dot(*a, dir)
                    } else {
                        dot(at, dir) + cross(sub(*a, at), u) / den
                    }
                }
            };
            (s, i)
        })
        .collect();
    st.sort_by(|a, b| a.0.partial_cmp(&b.0).unwrap_or(std::cmp::Ordering::Equal));
    Ok(Laid { dir, stations: st })
}

/// An angular dimension's angle, degrees, on the side of `at`.
fn angle(cx: &Ctx, d: &Dim) -> Result<f64, String> {
    let pr = cx.pr;
    let mut lines: Vec<(P, P)> = Vec::new();
    for (i, r) in d.refs.iter().enumerate() {
        let g = ref_geo(cx, r)?;
        if d.refs[..i].iter().any(|o| o.same(r)) {
            return Err(format!("it measures to {}'s {} twice", nm(pr, r), refs::what(r)));
        }
        match g {
            Geo::Point(_) => return Err(format!("it measures to an end of {}; an angle is between two lines", nm(pr, r))),
            Geo::Line(a, b) => {
                if let Some((fa, fb)) = lines.first() {
                    let f = unit(sub(*fb, *fa));
                    let u = unit(sub(b, a));
                    if cross(f, u).abs() <= PARALLEL {
                        return Err(format!("{} is parallel to {}; an angle is between lines that meet", nm(pr, r), nm(pr, &d.refs[0])));
                    }
                }
                lines.push((a, b));
            }
        }
    }
    let (a1, b1) = lines[0];
    let (a2, b2) = lines[1];
    let d1 = unit(sub(b1, a1));
    let d2 = unit(sub(b2, a2));
    let x = line_meet(a1, d1, a2, d2).unwrap_or(a1);
    let v = sub(d.at, x);
    // `at` as a sum of the two lines' ways: its signs pick the sector
    let den = cross(d1, d2);
    let s1 = cross(v, d2) / den;
    let s2 = cross(d1, v) / den;
    let r1 = mul(d1, s1.signum());
    let r2 = mul(d2, s2.signum());
    let c = dot(r1, r2).clamp(-1.0, 1.0);
    Ok(c.acos().to_degrees())
}

/// What is round: (centre, radius) of a radial or diameter dimension's reference.
fn radius(cx: &Ctx, d: &Dim) -> Result<f64, String> {
    let pr = cx.pr;
    let r = &d.refs[0];
    let Some(id) = r.id(pr) else {
        return Err(format!("element {} doesn't exist", r.guid()));
    };
    let e = pr.el(id).unwrap();
    let what = if d.kind == Kind::Diameter { "a diameter dimension" } else { "a radial dimension" };
    let g = refs::named_guid(pr, r);
    match cat(e) {
        "wall" => {
            let w = cx.wall(id).ok_or_else(|| format!("element {} doesn't exist", r.guid()))?;
            if w.b.straight() {
                return Err(format!("{} is straight; {} measures round columns and curved walls", g, what));
            }
            let off = match r.face {
                Face::Left => w.b.t / 2.0,
                Face::Right => -w.b.t / 2.0,
                _ => 0.0,
            };
            match w.b.carrier(off) {
                Carrier::Circle { r, .. } => Ok(r),
                _ => Ok(0.0),
            }
        }
        "line" => {
            let shape = geom::line_shape(e);
            match shape {
                Some(LineShape::Circle { r, .. }) | Some(LineShape::Arc { r, .. }) => Ok(r),
                Some(s) => Err(format!("{} is a {}; {} measures round columns and curved walls, circles and arcs", g, s.word(), what)),
                None => Err(format!("{} is a line; {} measures round columns and curved walls, circles and arcs", g, what)),
            }
        }
        _ => match geom::round_column(pr, e) {
            Some((_, rad)) => Ok(rad),
            None => Err(format!("{} isn't round; {} measures round columns and curved walls", g, what)),
        },
    }
}

/// The arc an arc length dimension measures along: centre, radius, start angle, sweep (radians).
fn the_arc(cx: &Ctx, r: &Ref) -> Result<(P, f64, f64, f64), String> {
    let pr = cx.pr;
    let Some(id) = r.id(pr) else {
        return Err(format!("element {} doesn't exist", r.guid()));
    };
    let e = pr.el(id).unwrap();
    let g = refs::named_guid(pr, r);
    const TAIL: &str = "an arc length dimension measures along curved walls and arcs";
    match cat(e) {
        "wall" => {
            let w = cx.wall(id).ok_or_else(|| format!("element {} doesn't exist", r.guid()))?;
            let Some((c, _, a0, sweep)) = w.b.circle() else {
                return Err(format!("{} is straight; {}", g, TAIL));
            };
            let off = match r.face {
                Face::Centre => 0.0,
                Face::Left => w.b.t / 2.0,
                Face::Right => -w.b.t / 2.0,
                _ => return Err(format!("{}'s ends are straight; {}", g, TAIL)),
            };
            match w.b.carrier(off) {
                Carrier::Circle { r, .. } => Ok((c, r, a0, sweep)),
                _ => Ok((c, 0.0, a0, sweep)),
            }
        }
        "line" => match geom::line_shape(e) {
            Some(LineShape::Arc { c, r, a0, sweep, .. }) => Ok((c, r, a0, sweep)),
            Some(LineShape::Circle { .. }) => Err(format!("{} is a circle, which has no ends; {}", g, TAIL)),
            Some(s) => Err(format!("{} is a {}; {}", g, s.word(), TAIL)),
            None => Err(format!("{} is a line; {}", g, TAIL)),
        },
        _ => Err(format!("{} isn't curved; {}", g, TAIL)),
    }
}

/// The fraction of an arc's sweep a point on its circle lies at (None: not on the arc).
fn on_arc(arc: (P, f64, f64, f64), p: P) -> Option<f64> {
    let (c, r, a0, sweep) = arc;
    let l = dist(p, c);
    if (l - r).abs() > 1e-3_f64.max(r * 1e-9) {
        return None;
    }
    let a = (p[1] - c[1]).atan2(p[0] - c[0]);
    let f = if sweep > 0.0 { wrap(a - a0) / sweep } else { wrap(a0 - a) / -sweep };
    let tol = 1e-9;
    if f <= 1.0 + tol {
        return Some(f.min(1.0));
    }
    // just short of a whole turn back to the start
    if (f * sweep.abs() - std::f64::consts::TAU).abs() < 1e-6 {
        return Some(0.0);
    }
    None
}

fn arc_length(cx: &Ctx, d: &Dim) -> Result<f64, String> {
    let pr = cx.pr;
    let arc = the_arc(cx, &d.refs[0])?;
    let whole = arc.1 * arc.3.abs();
    if d.refs.len() == 1 {
        return Ok(whole);
    }
    let mut fs = Vec::new();
    for (i, r) in d.refs.iter().enumerate().skip(1) {
        let g = ref_geo(cx, r)?;
        if d.refs[..i].iter().any(|o| o.same(r)) {
            return Err(format!("it measures to {}'s {} twice", nm(pr, r), refs::what(r)));
        }
        match g {
            Geo::Line(..) => return Err(format!("{} is measured to as a line", nm(pr, r))),
            Geo::Point(p) => match on_arc(arc, p) {
                Some(f) => fs.push(f),
                None => {
                    let end = r.point.unwrap_or(End::Start).word();
                    return Err(format!("{}'s {} isn't on the arc it measures along", nm(pr, r), end));
                }
            },
        }
    }
    Ok(whole * (fs[1] - fs[0]).abs())
}

/// A value as `values` gives it: to the hundredth.
pub fn r2(x: f64) -> f64 {
    let y = (x * 100.0).round() / 100.0;
    if y == 0.0 {
        0.0
    } else {
        y
    }
}

/// Whether a reference is to the target (the element of that GUID).
pub fn refers_to(r: &Ref, g: &str) -> bool {
    matches!(&r.target, Target::Guid(x) if x == g)
}

//! What a dimension's numbers read: lengths in its type's units (or the project's) and rounding,
//! as a continuous, baseline or ordinate string says, with its texts (prefix, suffix, Replace With
//! Text, Equality Display) and each segment's own over them.

use super::measure::Kind;
use super::super::common::*;
use crate::json::Value;
use crate::project::Project;

/// A length in mm as these units show it: millimetres, centimetres, metres, decimal feet,
/// fractional inches or feet and inches (to 1/16"); `decimals` where the type says (not for inches).
pub fn length_text(mm: f64, units: &str, decimals: Option<u64>) -> String {
    let fixed = |v: f64, d: u64| -> String {
        let k = 10f64.powi(d as i32);
        let n = (v * k).round();
        let x = n / k;
        let x = if x == 0.0 { 0.0 } else { x };
        format!("{:.*}", d as usize, x)
    };
    match units {
        "cm" => {
            let v = mm * 0.1;
            match decimals {
                Some(d) => fixed(v, d),
                None => {
                    let n = (v * 10.0).round();
                    let n = if n == 0.0 { 0.0 } else { n };
                    if n % 10.0 == 0.0 {
                        format!("{}", (n / 10.0) as i64)
                    } else {
                        format!("{:.1}", n / 10.0)
                    }
                }
            }
        }
        "m" => fixed(mm * 0.001, decimals.unwrap_or(2)),
        "ft" => format!("{}'", fixed(mm / 304.8, decimals.unwrap_or(2))),
        "in" => {
            let s = (mm / 25.4 * 16.0).round() as i64;
            inches_text(s)
        }
        "ft-in" => {
            let s = (mm / 25.4 * 16.0).round() as i64;
            let neg = s < 0;
            let s = s.abs();
            let feet = s / 192;
            let rest = s % 192;
            let inches = rest / 16;
            let frac = rest % 16;
            let f = if frac == 0 { format!("{}\"", inches) } else { format!("{} {}\"", inches, fraction(frac)) };
            format!("{}{}'-{}", if neg { "-" } else { "" }, feet, f)
        }
        _ => fixed(mm, decimals.unwrap_or(0)),
    }
}

/// Sixteenths of an inch as fractional inches: `39 3/8"`, `1/2"`, `12"`.
fn inches_text(s: i64) -> String {
    let neg = s < 0;
    let s = s.abs();
    let whole = s / 16;
    let frac = s % 16;
    let sign = if neg { "-" } else { "" };
    if frac == 0 {
        format!("{}{}\"", sign, whole)
    } else if whole == 0 {
        format!("{}{}\"", sign, fraction(frac))
    } else {
        format!("{}{} {}\"", sign, whole, fraction(frac))
    }
}

/// n/16 in lowest terms.
fn fraction(n: i64) -> String {
    let mut a = n;
    let mut b = 16;
    while a % 2 == 0 && b > 1 {
        a /= 2;
        b /= 2;
    }
    format!("{}/{}", a, b)
}

/// The dimension type's entry in `dimension_types` a dimension is of, by name.
pub fn type_of<'a>(pr: &'a Project, e: &Value) -> Option<(String, &'a Value)> {
    let name = lib_ref_name(pr, e, "type")?;
    let t = pr.section("dimension_types")?.get(&name)?;
    Some((name, t))
}

/// A dimension's or a segment's texts: prefix, suffix, above, below, replace.
#[derive(Clone, Debug, Default)]
pub struct Texts {
    pub prefix: Option<String>,
    pub suffix: Option<String>,
    pub above: Option<String>,
    pub below: Option<String>,
    pub replace: Option<String>,
}

pub const TEXT_KEYS: [&str; 5] = ["prefix", "suffix", "above", "below", "replace"];

impl Texts {
    pub fn of(v: &Value) -> Texts {
        let g = |k: &str| s_of(v, k).filter(|s| !s.is_empty()).map(|s| s.to_string());
        Texts { prefix: g("prefix"), suffix: g("suffix"), above: g("above"), below: g("below"), replace: g("replace") }
    }
    pub fn get(&self, k: &str) -> &Option<String> {
        match k {
            "prefix" => &self.prefix,
            "suffix" => &self.suffix,
            "above" => &self.above,
            "below" => &self.below,
            _ => &self.replace,
        }
    }
    pub fn set(&mut self, k: &str, v: Option<String>) {
        let v = v.filter(|s| !s.is_empty());
        match k {
            "prefix" => self.prefix = v,
            "suffix" => self.suffix = v,
            "above" => self.above = v,
            "below" => self.below = v,
            _ => self.replace = v,
        }
    }
    pub fn is_empty(&self) -> bool {
        TEXT_KEYS.iter().all(|k| self.get(k).is_none())
    }
    /// This segment's own over the dimension's where it says something.
    pub fn over(&self, base: &Texts) -> Texts {
        let mut t = base.clone();
        for k in TEXT_KEYS {
            if let Some(x) = self.get(k) {
                t.set(k, Some(x.clone()));
            }
        }
        t
    }
    /// A number with its texts: in place of it, or between the prefix and the suffix.
    pub fn around(&self, number: &str) -> String {
        if let Some(r) = &self.replace {
            return r.clone();
        }
        format!("{}{}{}", self.prefix.as_deref().unwrap_or(""), number, self.suffix.as_deref().unwrap_or(""))
    }
}

/// A dimension's segment texts, by segment.
pub fn segment_texts(e: &Value) -> Vec<(usize, Texts)> {
    let mut out = Vec::new();
    if let Some(a) = e.get("texts").and_then(|t| t.as_arr()) {
        for t in a {
            if let Some(s) = t.get("segment").and_then(|s| s.as_u64()) {
                out.push((s as usize, Texts::of(t)));
            }
        }
    }
    out
}

/// What a dimension's numbers read, from its values (unrounded).
pub fn labels(pr: &Project, e: &Value, kind: Kind, values: &[f64]) -> Vec<String> {
    let t = type_of(pr, e).map(|(_, t)| t.clone()).unwrap_or(Value::Null);
    let units = s_of(&t, "units").map(|s| s.to_string()).unwrap_or_else(|| crate::styles::weights::project_units(pr));
    let decimals = t.get("decimals").and_then(|d| d.as_u64());
    let len = |v: f64| length_text(v, &units, decimals);
    let own = Texts::of(e);
    let segs = segment_texts(e);
    let texts_of = |i: usize| -> Texts {
        match segs.iter().find(|(s, _)| *s == i) {
            Some((_, t)) => t.over(&own),
            None => own.clone(),
        }
    };
    match kind {
        Kind::Aligned | Kind::Linear => {
            if e.get("equality").and_then(|x| x.as_bool()) == Some(true) {
                let eq = s_of(&t, "equality_text").unwrap_or("EQ").to_string();
                let n = match s_of(&t, "string") {
                    Some("ordinate") => values.len() + 1,
                    _ => values.len(),
                };
                return vec![eq; n];
            }
            let numbers: Vec<f64> = match s_of(&t, "string") {
                Some("baseline") => {
                    let mut acc = 0.0;
                    values.iter().map(|v| {
                        acc += v;
                        acc
                    }).collect()
                }
                Some("ordinate") => {
                    let mut acc = 0.0;
                    let mut v = vec![0.0];
                    for x in values {
                        acc += x;
                        v.push(acc);
                    }
                    v
                }
                _ => values.to_vec(),
            };
            numbers.iter().enumerate().map(|(i, v)| texts_of(i).around(&len(*v))).collect()
        }
        Kind::Angular => values.iter().enumerate().map(|(i, v)| texts_of(i).around(&format!("{}°", super::measure::r2(*v)))).collect(),
        Kind::Radial | Kind::Diameter => {
            let key = if kind == Kind::Radial { "radius_symbol" } else { "diameter_symbol" };
            let sym = s_of(&t, key).unwrap_or(if kind == Kind::Radial { "R" } else { "Ø" }).to_string();
            values
                .iter()
                .enumerate()
                .map(|(i, v)| {
                    let n = if sym.is_empty() { len(*v) } else { format!("{} {}", sym, len(*v)) };
                    texts_of(i).around(&n)
                })
                .collect()
        }
        Kind::ArcLength => values.iter().enumerate().map(|(i, v)| texts_of(i).around(&len(*v))).collect(),
    }
}

