//! A reference picked by a point: the nearest line of what the plan cuts (a wall's centre line,
//! faces and ends, a door's or window's centre and jambs, a grid), the nearest end (`{endpoint}`),
//! or the nearest round edge or arc, within 100 mm.

use super::geom::{self, *};
use super::measure::{Ctx, Kind};
use super::refs::{End, Face, Ref, Target};
use super::super::common::*;
use crate::json::Value;
use crate::project::Project;

/// The plan a dimension is in: its level, and the plan view where it is in one.
#[derive(Clone, Copy, Debug)]
pub struct Plan {
    pub level: u64,
    pub view: Option<u64>,
}

impl Plan {
    /// The height the plan cuts at.
    pub fn cut(&self, pr: &Project) -> f64 {
        let lv = pr.el(self.level).and_then(|e| f_of(e, "elevation")).unwrap_or(0.0);
        let key = self.view.unwrap_or(self.level);
        let mut src = key;
        // a dependent view follows its parent's view range
        if let Some(e) = pr.el(key) {
            if let Some(p) = ref_id(pr, e, "parent") {
                src = p;
            }
        }
        let cut = pr
            .el(src)
            .and_then(|e| e.get("view_range"))
            .and_then(|v| f_of(v, "cut"))
            .unwrap_or(1200.0);
        lv + cut
    }
    /// The plan's name in messages: its level's.
    pub fn name(&self, pr: &Project) -> String {
        name_of(pr, self.level)
    }
    /// The views whose detail lines it shows: its own (and a dependent view's parent's).
    fn line_views(&self, pr: &Project) -> Vec<String> {
        let key = self.view.unwrap_or(self.level);
        let mut v = vec![guid(pr, key)];
        if let Some(e) = pr.el(key) {
            if let Some(p) = s_of(e, "parent") {
                v.push(p.to_string());
            }
        }
        v
    }
}

/// Whether the plan cuts a wall (or a column): it spans the plan's cut height.
fn cut_by(pr: &Project, plan: &Plan, base: f64, top: f64) -> bool {
    let h = plan.cut(pr);
    base <= h && h <= top
}

fn fmt_pt(p: P) -> String {
    format!("[{}, {}]", disp(p[0]), disp(p[1]))
}

/// The walls the plan cuts, joined.
fn cut_walls<'a>(cx: &'a Ctx, plan: &Plan) -> Vec<&'a Wall> {
    cx.walls().iter().filter(|w| cut_by(cx.pr, plan, w.b.base, w.b.top)).collect()
}

/// The doors and windows in those walls, by id.
fn openings(pr: &Project, walls: &[&Wall], c: &str) -> Vec<u64> {
    let hosts: Vec<&str> = walls.iter().map(|w| w.b.guid.as_str()).collect();
    pr.ids_of(c).into_iter().filter(|id| pr.el(*id).and_then(|e| s_of(e, "host")).map_or(false, |h| hosts.contains(&h))).collect()
}

/// The detail lines in the plan, by id.
fn plan_lines(pr: &Project, plan: &Plan) -> Vec<u64> {
    let views = plan.line_views(pr);
    pr.ids_of("line").into_iter().filter(|id| pr.el(*id).and_then(|e| s_of(e, "view")).map_or(false, |v| views.iter().any(|x| x == v))).collect()
}

struct Best {
    d: f64,
    r: Option<Ref>,
}

impl Best {
    fn new() -> Best {
        Best { d: f64::INFINITY, r: None }
    }
    fn offer(&mut self, d: f64, pr: &Project, id: u64, face: Face, point: Option<End>) {
        if d <= PICK && d < self.d {
            self.d = d;
            self.r = Some(Ref { target: Target::Guid(guid(pr, id)), face, point });
        }
    }
}

/// The line nearest a point, of what an aligned, linear or angular dimension measures to.
pub fn line_at(cx: &Ctx, plan: &Plan, p: P) -> Result<Ref, String> {
    let pr = cx.pr;
    let mut best = Best::new();
    let walls = cut_walls(cx, plan);
    for w in &walls {
        let id = w.id();
        if w.b.straight() {
            best.offer(seg_dist(p, w.b.cl.start, w.b.cl.end), pr, id, Face::Centre, None);
            best.offer(seg_dist(p, w.left.0, w.left.1), pr, id, Face::Left, None);
            best.offer(seg_dist(p, w.right.0, w.right.1), pr, id, Face::Right, None);
        } else {
            for (off, f) in [(0.0, Face::Centre), (w.b.t / 2.0, Face::Left), (-w.b.t / 2.0, Face::Right)] {
                best.offer(arc_dist(&w.b, off, p), pr, id, f, None);
            }
        }
        best.offer(seg_dist(p, w.sface.0, w.sface.1), pr, id, Face::Start, None);
        best.offer(seg_dist(p, w.eface.0, w.eface.1), pr, id, Face::End, None);
    }
    for c in ["door", "window"] {
        for id in openings(pr, &walls, c) {
            if let Some((_, ls)) = geom::opening_lines(pr, id) {
                for (l, f) in ls.iter().zip([Face::Centre, Face::Start, Face::End]) {
                    best.offer(seg_dist(p, l.0, l.1), pr, id, f, None);
                }
            }
        }
    }
    for id in pr.ids_of("grid") {
        let e = pr.el(id).unwrap();
        let a = pt_of(e, "start").unwrap_or([0.0, 0.0]);
        let b = pt_of(e, "end").unwrap_or([0.0, 0.0]);
        best.offer(seg_dist(p, a, b), pr, id, Face::Centre, None);
    }
    best.r.ok_or_else(|| {
        format!(
            "no wall face, wall centre line, wall end, door, window or grid line at {} on {}",
            fmt_pt(p),
            plan.name(pr)
        )
    })
}

/// How far a point is from a curved wall's arc `off` left of its centre line.
fn arc_dist(w: &WallBase, off: f64, p: P) -> f64 {
    let Some((c, _, a0, sweep)) = w.circle() else { return f64::INFINITY };
    let Carrier::Circle { r, .. } = w.carrier(off) else { return f64::INFINITY };
    arc_point_dist(c, r, a0, sweep, p)
}

/// How far a point is from an arc (its nearest point on it, or an end).
pub fn arc_point_dist(c: P, r: f64, a0: f64, sweep: f64, p: P) -> f64 {
    let a = (p[1] - c[1]).atan2(p[0] - c[0]);
    let f = if sweep > 0.0 { wrap(a - a0) / sweep } else { wrap(a0 - a) / -sweep };
    if f <= 1.0 {
        return (dist(p, c) - r).abs();
    }
    let s = [c[0] + r * a0.cos(), c[1] + r * a0.sin()];
    let e = [c[0] + r * (a0 + sweep).cos(), c[1] + r * (a0 + sweep).sin()];
    dist(p, s).min(dist(p, e))
}

/// The end nearest a point: of a wall's centre line or faces, a door's or window's lines, a grid,
/// a detail line.
pub fn end_at(cx: &Ctx, plan: &Plan, p: P) -> Result<Ref, String> {
    let pr = cx.pr;
    let mut best = Best::new();
    let walls = cut_walls(cx, plan);
    for w in &walls {
        let id = w.id();
        for (l, f) in [((w.b.cl.start, w.b.cl.end), Face::Centre), (w.left, Face::Left), (w.right, Face::Right), (w.sface, Face::Start), (w.eface, Face::End)] {
            best.offer(dist(p, l.0), pr, id, f, Some(End::Start));
            best.offer(dist(p, l.1), pr, id, f, Some(End::End));
        }
    }
    for c in ["door", "window"] {
        for id in openings(pr, &walls, c) {
            if let Some((_, ls)) = geom::opening_lines(pr, id) {
                for (l, f) in ls.iter().zip([Face::Centre, Face::Start, Face::End]) {
                    best.offer(dist(p, l.0), pr, id, f, Some(End::Start));
                    best.offer(dist(p, l.1), pr, id, f, Some(End::End));
                }
            }
        }
    }
    for id in pr.ids_of("grid") {
        let e = pr.el(id).unwrap();
        let a = pt_of(e, "start").unwrap_or([0.0, 0.0]);
        let b = pt_of(e, "end").unwrap_or([0.0, 0.0]);
        best.offer(dist(p, a), pr, id, Face::Centre, Some(End::Start));
        best.offer(dist(p, b), pr, id, Face::Centre, Some(End::End));
    }
    for id in plan_lines(pr, plan) {
        if let Some(s) = geom::line_shape(pr.el(id).unwrap()) {
            let (a, b) = s.ends();
            best.offer(dist(p, a), pr, id, Face::Centre, Some(End::Start));
            best.offer(dist(p, b), pr, id, Face::Centre, Some(End::End));
        }
    }
    best.r.ok_or_else(|| {
        format!(
            "no end of a wall, a wall face, a door, a window, a grid or a detail line at {} on {}",
            fmt_pt(p),
            plan.name(pr)
        )
    })
}

/// The round edge nearest a point (radial and diameter: a round column, a curved wall's centre
/// line or face, a circle or an arc), or the arc (arc length: a curved wall's, a detail line's).
pub fn round_at(cx: &Ctx, plan: &Plan, p: P, kind: Kind) -> Result<Ref, String> {
    let pr = cx.pr;
    let mut best = Best::new();
    let arcs_only = kind == Kind::ArcLength;
    if !arcs_only {
        for c in ["column", "structuralcolumn", "footing"] {
            for id in pr.ids_of(c) {
                let e = pr.el(id).unwrap();
                if let Some((ctr, r)) = geom::round_column(pr, e) {
                    let (base, top) = super::super::model::base_top(pr, e);
                    if cut_by(pr, plan, base, top) {
                        best.offer((dist(p, ctr) - r).abs(), pr, id, Face::Centre, None);
                    }
                }
            }
        }
    }
    for w in cut_walls(cx, plan) {
        if w.b.straight() {
            continue;
        }
        for (off, f) in [(0.0, Face::Centre), (w.b.t / 2.0, Face::Left), (-w.b.t / 2.0, Face::Right)] {
            best.offer(arc_dist(&w.b, off, p), pr, w.id(), f, None);
        }
    }
    for id in plan_lines(pr, plan) {
        match geom::line_shape(pr.el(id).unwrap()) {
            Some(LineShape::Arc { c, r, a0, sweep, .. }) => best.offer(arc_point_dist(c, r, a0, sweep, p), pr, id, Face::Centre, None),
            Some(LineShape::Circle { c, r }) if !arcs_only => best.offer((dist(p, c) - r).abs(), pr, id, Face::Centre, None),
            _ => {}
        }
    }
    best.r.ok_or_else(|| {
        if arcs_only {
            format!("no curved wall or arc at {} on {}", fmt_pt(p), plan.name(pr))
        } else {
            format!("no round column's, curved wall's, circle's or arc's edge at {} on {}", fmt_pt(p), plan.name(pr))
        }
    })
}

/// Everything a reference's element spans in plan, for where `at` lies (a linear dimension's way).
pub fn extent(cx: &Ctx, r: &Ref) -> Vec<P> {
    let pr = cx.pr;
    let Some(id) = r.id(pr) else { return Vec::new() };
    let e: &Value = pr.el(id).unwrap();
    match cat(e) {
        "wall" => cx.wall(id).map(|w| w.outline()).unwrap_or_default(),
        "door" | "window" => geom::opening_lines(pr, id).map(|(_, ls)| ls.iter().flat_map(|l| [l.0, l.1]).collect()).unwrap_or_default(),
        "grid" => [pt_of(e, "start"), pt_of(e, "end")].into_iter().flatten().collect(),
        "line" => geom::line_shape(e).map(|s| s.points()).unwrap_or_default(),
        _ => Vec::new(),
    }
}

//! Dimensions: `dimension` (aligned, linear, angular, radial, diameter, arc length).

pub mod geom;
pub mod labels;
pub mod measure;
pub mod pick;
pub mod refs;

use super::common::*;
use crate::json::{Map, Value};
use crate::project::Project;
use crate::session::Session;
use measure::{Ctx, Dim, Kind, Orient};
use refs::{RefIn, Target};

const CMD: &str = "dimension";

/// The dimension type a kind starts in.
pub fn default_type(kind: Kind) -> &'static str {
    match kind {
        Kind::Radial | Kind::Diameter => "Arrow - 2.5mm Arial",
        _ => "Diagonal - 2.5mm Arial",
    }
}

/// The project's dimension types' names, as the original lists them.
pub fn type_names(pr: &Project) -> Vec<String> {
    let mut v: Vec<String> = match pr.section("dimension_types") {
        Some(m) => m.keys().cloned().collect(),
        None => vec!["Arrow - 2.5mm Arial".into(), "Diagonal - 2.5mm Arial".into()],
    };
    v.sort();
    v
}

/// The GUID of a dimension type by name: its library entry's (made where the project has the
/// type but not yet the entry).
fn type_guid(pr: &mut Project, name: &str) -> Option<String> {
    if !type_names(pr).iter().any(|n| n == name) {
        return None;
    }
    Some(match pr.lib_guid("dimension-type", name) {
        Some(g) => g,
        None => pr.lib_add("dimension-type", name).1,
    })
}

/// Runs the commands of this part.
pub fn run(s: &mut Session, cid: &str, p: &Value) -> R<Value> {
    match cid {
        "dimension" => dimension(&mut s.project, p),
        _ => Err(format!("{}: not supported here", cid)),
    }
}

/// A text parameter: None when absent or null.
fn text(p: &Value, key: &str) -> R<Option<String>> {
    crate::commands::params::opt_text(p, CMD, key)
}

/// The plan a `level` parameter names: a level, or a plan view (and its level).
pub fn plan_param(pr: &Project, cmd: &str, p: &Value) -> R<pick::Plan> {
    let level = crate::model::level_param(pr, cmd, p, "level")?;
    let mut view = None;
    if let Some(v) = get(p, "level") {
        if let Some(id) = crate::model::find(pr, v) {
            if pr.category(id) == Some("planview") {
                view = Some(id);
            }
        } else if let Value::Str(s) = v {
            let is_level = crate::model::levels(pr).iter().any(|l| name_of(pr, *l) == *s);
            if !is_level {
                view = pr.ids_of("planview").into_iter().find(|id| name_of(pr, *id) == *s);
            }
        }
    }
    Ok(pick::Plan { level, view })
}

fn dimension(pr: &mut Project, p: &Value) -> R<Value> {
    let plan = plan_param(pr, CMD, p)?;
    let at = crate::commands::params::req_point(p, CMD, "at")?;
    let kind = match text(p, "kind")? {
        None => Kind::Aligned,
        Some(k) => Kind::parse(&k).ok_or_else(|| format!("{}: `kind` is aligned, linear, angular, radial, diameter or arc_length, not `{}`", CMD, k))?,
    };
    let orient = match text(p, "orient")? {
        None => None,
        Some(o) => Some(Orient::parse(&o).ok_or_else(|| format!("{}: `orient` is horizontal or vertical, not `{}`", CMD, o))?),
    };
    let type_name = text(p, "type")?.map(|t| t.trim().to_string()).filter(|t| !t.is_empty());
    let mut texts: Vec<(&str, String)> = Vec::new();
    for k in labels::TEXT_KEYS {
        if let Some(t) = text(p, k)? {
            texts.push((k, t));
        }
    }
    let equality = crate::commands::params::opt_bool(p, CMD, "equality")?;
    let Some(raw) = get(p, "refs").and_then(|r| r.as_arr()) else {
        return Err(format!("{}: `refs` [ref, …] is required", CMD));
    };
    // each reference read, and a point found its line, in order
    let mut rs = Vec::new();
    {
        let cx = Ctx::new(pr);
        for v in raw {
            let r = match refs::parse_ref_in(v).map_err(|e| format!("{}: {}", CMD, e))? {
                RefIn::Ref { id, face, point } => refs::Ref { target: refs::target_of(pr, &id), face, point },
                RefIn::Point(q) => match kind {
                    Kind::Radial | Kind::Diameter | Kind::ArcLength => pick::round_at(&cx, &plan, q, kind),
                    _ => pick::line_at(&cx, &plan, q),
                }
                .map_err(|e| format!("{}: {}", CMD, e))?,
                RefIn::Endpoint(q) => pick::end_at(&cx, &plan, q).map_err(|e| format!("{}: {}", CMD, e))?,
            };
            rs.push(r);
        }
    }
    let id = pr.alloc_id();
    // a linear one without `orient` runs vertical where `at` is east or west of all it measures
    let orient = match (kind, orient) {
        (Kind::Linear, None) => {
            let cx = Ctx::new(pr);
            let xs: Vec<f64> = rs.iter().flat_map(|r| pick::extent(&cx, r)).map(|p| p[0]).collect();
            let lo = xs.iter().cloned().fold(f64::INFINITY, f64::min);
            let hi = xs.iter().cloned().fold(f64::NEG_INFINITY, f64::max);
            if !xs.is_empty() && (at[0] > hi || at[0] < lo) {
                Some(Orient::Vertical)
            } else {
                Some(Orient::Horizontal)
            }
        }
        (_, o) => o,
    };
    let tname = type_name.clone().unwrap_or_else(|| default_type(kind).to_string());
    let Some(tguid) = type_guid(pr, &tname) else {
        return Err(format!("{} {}: there's no dimension type `{}` (there are: {})", CMD, id, tname, type_names(pr).join(", ")));
    };
    let mut e = Map::new();
    e.insert("guid", Value::s(&crate::rand::guid()));
    e.insert("category", Value::s("dimension"));
    e.insert("level", Value::s(&guid(pr, plan.level)));
    if let Some(v) = plan.view {
        e.insert("view", Value::s(&guid(pr, v)));
    }
    e.insert("kind", Value::s(kind.word()));
    if let Some(o) = orient {
        e.insert("orient", Value::s(o.word()));
    }
    e.insert("refs", Value::Arr(rs.iter().map(|r| r.to_value()).collect()));
    e.insert("at", Value::from(at));
    e.insert("type", Value::s(&tguid));
    for (k, t) in &texts {
        if !t.is_empty() {
            e.insert(k, Value::s(t));
        }
    }
    if equality == Some(true) {
        e.insert("equality", Value::Bool(true));
    }
    pr.elements.insert(id, Value::Obj(e));
    let values = check_one(&Ctx::new(pr), id)?;
    Ok(jobj! {"id" => id, "values" => Value::Arr(values.iter().map(|v| Value::f(measure::r2(*v))).collect())})
}

/// One dimension's rules (its type's first): its values, or "dimension N: …".
pub fn check_one(cx: &Ctx, id: u64) -> R<Vec<f64>> {
    let pr = cx.pr;
    let e = pr.el(id).ok_or_else(|| format!("no element {}", id))?;
    let tname = lib_ref_name(pr, e, "type");
    let names = type_names(pr);
    match &tname {
        Some(n) if names.contains(n) => {}
        _ => {
            let n = tname.clone().unwrap_or_else(|| s_of(e, "type").unwrap_or("").to_string());
            return Err(format!("dimension {}: there's no dimension type `{}` (there are: {})", id, n, names.join(", ")));
        }
    }
    let d = Dim::from_element(id, e);
    measure::measure(cx, &d).map_err(|m| format!("dimension {}: {}", id, m))
}

/// The model rules of this part, checked after every command.
pub fn check(pr: &Project) -> R<()> {
    let ids = pr.ids_of("dimension");
    if ids.is_empty() {
        return Ok(());
    }
    let cx = Ctx::new(pr);
    for id in ids {
        check_one(&cx, id)?;
    }
    Ok(())
}

/// A dimension's values as `elements` and the replies give them (to the hundredth).
pub fn values(pr: &Project, id: u64) -> Vec<f64> {
    let cx = Ctx::new(pr);
    match pr.el(id) {
        Some(e) => measure::measure(&cx, &Dim::from_element(id, e)).unwrap_or_default(),
        None => Vec::new(),
    }
}

/// What a dimension's numbers read.
pub fn dimension_labels(pr: &Project, id: u64) -> Vec<String> {
    let Some(e) = pr.el(id) else { return Vec::new() };
    let d = Dim::from_element(id, e);
    let v = values(pr, id);
    labels::labels(pr, e, d.kind, &v)
}

/// What `elements` shows of this part's elements beyond their own fields.
pub fn element_view(pr: &Project, id: u64, x: &mut Value) {
    let Some(e) = pr.el(id) else { return };
    let d = Dim::from_element(id, e);
    let v = values(pr, id);
    let ls = labels::labels(pr, e, d.kind, &v);
    x.set("labels", Value::Arr(ls.into_iter().map(Value::from).collect()));
    x.set("values", Value::Arr(v.iter().map(|v| Value::f(measure::r2(*v))).collect()));
    if let Some(n) = lib_ref_name(pr, e, "type") {
        x.set("type", Value::s(&n));
    }
    let _ = Target::Missing(String::new());
}

