#!/usr/bin/env python3
"""moveprobe.py [-m] project 'cmd' ... : runs the commands and prints walls' start/end and doors' offsets."""
import subprocess, json, os, tempfile, shutil, sys
exe = '/workspace/executable'
a = sys.argv[1:]
if a[0] == '-m':
    exe = os.environ['MINE']; a = a[1:]
proj = a[0]
d = tempfile.mkdtemp(dir='/tmp/views-dims')
shutil.copy(proj, d)
args = [exe, 'run', os.path.basename(proj)]
for c in a[1:]:
    args += ['--cmd', c]
args += ['--save', 'out.bimcraft']
p = subprocess.run(args, cwd=d, capture_output=True)
print(p.stdout.decode().strip().split('\n')[1:-1], p.stderr.decode().strip())
try:
    pr = json.load(open(os.path.join(d, 'out.bimcraft')))
    for k, e in pr['elements'].items():
        if e['category'] == 'wall':
            print(k, 'wall', e['start'], e['end'], e.get('arc', ''))
        elif e['category'] in ('door', 'window'):
            print(k, e['category'], repr(e['offset']))
        elif e['category'] == 'grid':
            print(k, 'grid', e['start'], e['end'])
except Exception as x:
    print('no save', x)
shutil.rmtree(d)

