import math, itertools
# observed door offsets after moving the west wall of the box by dx (door at 2000 in the south wall)
data={-1:'2001.0',-2:'2002.0',-3:'2003.0',-10:'2010.0',-100:'2100.0',-500:'2500.0',-999:'2999.0',-1001:'3001.0',-1500:'3500.0',-2000:'4000.0',-3000:'5000.0',-4000:'6000.0',-5000:'7000.0',-7000:'9000.0',-0.5:'2000.5',500:'1500.0',1500:'500.0',-1000:'2999.9999999999995',-333:'2333.0',1000:'1000.0'}
def cross(a,b): return a[0]*b[1]-a[1]*b[0]
def sub(a,b): return (a[0]-b[0],a[1]-b[1])
def add(a,b): return (a[0]+b[0],a[1]+b[1])
def mul(a,k): return (a[0]*k,a[1]*k)
def dot(a,b): return a[0]*b[0]+a[1]*b[1]
def u_div(v):
    l=math.sqrt(v[0]*v[0]+v[1]*v[1]); return (v[0]/l, v[1]/l)
def u_hyp(v):
    l=math.hypot(v[0],v[1]); return (v[0]/l, v[1]/l)
def u_ang(v):
    a=math.atan2(v[1],v[0]); return (math.cos(a), math.sin(a))
def u_raw(v): return v
units={'div':u_div,'hyp':u_hyp,'ang':u_ang,'raw':u_raw}
# lines: moved west wall W from (dx,6000) to (dx,0); south wall S from (0,0) to (10000,0)
def inters(kind, a, da, c, dc):
    if kind==0:
        t=cross(sub(c,a),dc)/cross(da,dc); return add(a,mul(da,t))
    if kind==1:
        t=cross(sub(a,c),da)/cross(dc,da); return add(c,mul(dc,t))
    if kind==2:
        # normal form: n.p = k
        n1=(-da[1],da[0]); k1=dot(n1,a)
        n2=(-dc[1],dc[0]); k2=dot(n2,c)
        det=n1[0]*n2[1]-n1[1]*n2[0]
        return ((k1*n2[1]-k2*n1[1])/det, (n1[0]*k2-n2[0]*k1)/det)
    if kind==3:
        # parametric with projection onto the other's normal
        n2=(-dc[1],dc[0]); t=dot(sub(c,a),n2)/dot(da,n2); return add(a,mul(da,t))
    if kind==4:
        n1=(-da[1],da[0]); s=dot(sub(a,c),n1)/dot(dc,n1); return add(c,mul(dc,s))
hits={}
for dx,want in data.items():
    W=[(dx,6000.0),(dx,0.0)]; S=[(0.0,0.0),(10000.0,0.0)]
    for un,uf in units.items():
      for un2,uf2 in units.items():
        for wa in (0,1):
          for sa in (0,1):
            for wsign in (1,-1):
              for ssign in (1,-1):
                for kind in range(5):
                    da=uf(mul(sub(W[1],W[0]),wsign)); dc=uf2(mul(sub(S[1],S[0]),ssign))
                    try:
                        p=inters(kind,W[wa],da,S[sa],dc)
                    except ZeroDivisionError:
                        continue
                    # door offset: from the unrounded start, along the new wall
                    for on in ('x','dot'):
                        if on=='x': off=2000-p[0]
                        else:
                            d=u_div(sub((10000.0,0.0),p)); off=dot(sub((2000.0,0.0),p),d)
                        key=(un,un2,wa,sa,wsign,ssign,kind,on)
                        hits.setdefault(key,[]).append(repr(off)==want)
for k,v in hits.items():
    if all(v): print(k)
print('done')

