#!/usr/bin/env python3
"""randdim2.py project seed n: random dimension commands near the project's elements, compared."""
import subprocess, json, os, sys, random, tempfile, shutil, re
orig = '/workspace/executable'
mine = '/workspace/.claude/worktrees/agent-aa68fa9ebdf329369/target/release/bimcraft-cli'
proj, seed, n = sys.argv[1], int(sys.argv[2]), int(sys.argv[3])
random.seed(seed)
pr = json.load(open(proj))
els = pr['elements']
ids = [k for k, e in els.items() if e['category'] in ('wall', 'door', 'window', 'grid', 'line', 'column')]
pts = []
for e in els.values():
    for k in ('start', 'end', 'at', 'centre'):
        if k in e and isinstance(e[k], list):
            pts.append(e[k])
G = re.compile(r'[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}')
def norm(s):
    m = {}
    def rep(mo):
        g = mo.group(0)
        if g not in m: m[g] = 'G%d' % len(m)
        return m[g]
    return G.sub(rep, s)
def near():
    p = random.choice(pts)
    return [p[0] + random.randint(-4, 4) * 50, p[1] + random.randint(-4, 4) * 50]
def ref():
    r = random.random()
    if r < 0.25:
        return near()
    if r < 0.35:
        return {"endpoint": near()}
    x = {"id": int(random.choice(ids))}
    if random.random() < 0.6:
        x["face"] = random.choice(['centre', 'left', 'right', 'start', 'end'])
    if random.random() < 0.3:
        x["point"] = random.choice(['start', 'end'])
    return x
same = 0
for i in range(n):
    k = random.choice(['aligned', 'aligned', 'aligned', 'linear', 'angular', 'radial', 'diameter', 'arc_length'])
    m = {'radial': 1, 'diameter': 1, 'arc_length': random.choice([1, 3]), 'angular': 2}.get(k, random.randint(2, 4))
    p = {"refs": [ref() for _ in range(m)], "at": near()}
    if k != 'aligned':
        p["kind"] = k
    if k == 'linear' and random.random() < 0.5:
        p["orient"] = random.choice(['horizontal', 'vertical'])
    cmd = 'dimension ' + json.dumps(p)
    outs = []
    for exe in (orig, mine):
        d = tempfile.mkdtemp(dir='/tmp/views-dims')
        shutil.copy(proj, d)
        q = subprocess.run([exe, 'run', os.path.basename(proj), '--cmd', cmd, '--cmd', 'elements {"category":"dimension"}'], cwd=d, capture_output=True, text=True)
        shutil.rmtree(d)
        outs.append(norm(q.stdout.strip().split('\n')[-1] + ' ' + q.stderr.strip()))
    if outs[0] == outs[1]:
        same += 1
    else:
        print('DIFF', cmd)
        print('  orig', outs[0][:500])
        print('  mine', outs[1][:500])
print('%d/%d same' % (same, n))

