#!/usr/bin/env python3
"""randkeep.py project seed n: random sequences of dimensions, constraints, texts and typed values,
comparing the outputs and the saved projects of both programs."""
import subprocess, json, os, sys, random, tempfile, shutil, re
orig = '/workspace/executable'
mine = '/workspace/.claude/worktrees/agent-aa68fa9ebdf329369/target/release/bimcraft-cli'
proj, seed, n = sys.argv[1], int(sys.argv[2]), int(sys.argv[3])
random.seed(seed)
pr = json.load(open(proj))
els = pr['elements']
G = re.compile(r'[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}')
def norm(s):
    m = {}
    def rep(mo):
        g = mo.group(0)
        if g not in m: m[g] = 'G%d' % len(m)
        return m[g]
    s = re.sub(r'"uid": \d+', '"uid": 0', s)
    return G.sub(rep, s)
# horizontal and vertical things to dimension between
def lines(axis):
    out = []
    for k, e in els.items():
        if e['category'] in ('wall', 'grid', 'line') and 'start' in e and 'end' in e and 'arc' not in e:
            (x0, y0), (x1, y1) = e['start'], e['end']
            if axis == 'v' and abs(x0 - x1) < 1e-6:
                out.append(int(k))
            if axis == 'h' and abs(y0 - y1) < 1e-6:
                out.append(int(k))
        if e['category'] in ('door', 'window'):
            host = [h for h, x in els.items() if x.get('guid') == e['host']][0]
            (x0, y0), (x1, y1) = els[host]['start'], els[host]['end']
            if axis == 'v' and abs(y0 - y1) < 1e-6:
                out.append(int(k))
            if axis == 'h' and abs(x0 - x1) < 1e-6:
                out.append(int(k))
    return out
same = 0
for t in range(n):
    cmds = []
    ndims = 0
    for i in range(random.randint(1, 3)):
        axis = random.choice('vh')
        cand = lines(axis)
        if len(cand) < 2:
            continue
        refs = random.sample(cand, min(len(cand), random.randint(2, 4)))
        cmds.append('dimension {"refs":%s,"at":[%d,%d]}' % (json.dumps([{"id": r} for r in refs]), random.randint(0, 12000), random.randint(0, 8000)))
        ndims += 1
    if not ndims:
        continue
    first = max(int(k) for k in els) + 1
    for i in range(random.randint(1, 4)):
        d = first + random.randint(0, ndims - 1)
        r = random.random()
        if r < 0.35:
            segs = sorted(random.sample(range(3), random.randint(0, 2)))
            c = {"id": d, "locked": segs}
            if random.random() < 0.3:
                c["equal"] = random.choice([True, False])
            cmds.append('dimension_constraint ' + json.dumps(c))
        elif r < 0.5:
            cmds.append('dimension_constraint {"id":%d,"equal":true}' % d)
        elif r < 0.85:
            cmds.append('dimension_value {"id":%d,"value":%d,"segment":%d}' % (d, random.randint(5, 80) * 100, random.randint(0, 2)))
        else:
            cmds.append('dimension_text {"id":%d,"segment":%d,"prefix":"p"}' % (d, random.randint(0, 2)))
    outs = []
    for exe in (orig, mine):
        dd = tempfile.mkdtemp(dir='/tmp/views-dims')
        shutil.copy(proj, dd)
        args = [exe, 'run', os.path.basename(proj)]
        for c in cmds:
            args += ['--cmd', c]
        args += ['--cmd', 'elements {"category":"dimension"}', '--save', 'out.bimcraft']
        q = subprocess.run(args, cwd=dd, capture_output=True, text=True)
        f = os.path.join(dd, 'out.bimcraft')
        saved = open(f).read() if os.path.exists(f) else ''
        shutil.rmtree(dd)
        outs.append((norm(q.stdout + q.stderr), norm(saved)))
    if outs[0] == outs[1]:
        same += 1
    else:
        print('DIFF', ' ;; '.join(cmds))
        a, b = outs[0], outs[1]
        if a[0] != b[0]:
            la, lb = a[0].split('\n'), b[0].split('\n')
            for x, y in zip(la, lb):
                if x != y:
                    print('  orig', x[:400]); print('  mine', y[:400]); break
        else:
            la, lb = a[1].split('\n'), b[1].split('\n')
            for i, (x, y) in enumerate(zip(la, lb)):
                if x != y:
                    print('  file line', i, 'orig', x[:200]); print('                mine', y[:200]); break
print('%d/%d same' % (same, n))

