#!/usr/bin/env python3
"""pt.py [-m] project.bimcraft hgrid vgrid ref_json... : prints each point ref's x, y measured from
a horizontal grid at y=-50000 (id hgrid) and a vertical one at x=-50000 (id vgrid)."""
import json, os, subprocess, sys, tempfile, shutil
exe = '/workspace/executable'
a = sys.argv[1:]
if a[0] == '-m':
    exe = os.environ['MINE']; a = a[1:]
proj, hg, vg = a[0], a[1], a[2]
def run(cmd):
    d = tempfile.mkdtemp(prefix='pt', dir='/tmp/views-dims')
    shutil.copy(proj, d)
    p = subprocess.run([exe, 'run', os.path.basename(proj), '--cmd', cmd], cwd=d, capture_output=True, timeout=60)
    shutil.rmtree(d)
    out = p.stdout.decode().strip().split('\n')[-1]
    try:
        return json.loads(out)['values']
    except Exception:
        return p.stderr.decode().strip()
for r in a[3:]:
    y = run('dimension {"refs":[{"id":%s},%s],"at":[-60000,-60000]}' % (hg, r))
    x = run('dimension {"refs":[{"id":%s},%s],"at":[-60000,-60000]}' % (vg, r))
    try:
        print(r, '->', [round(x[0] - 50000, 3), round(y[0] - 50000, 3)])
    except Exception:
        print(r, '->', x, y)

