#!/usr/bin/env python3
"""limit3.py files...: scores many ways of computing a corner's mitre reach against the
original's choices recorded by bound.py."""
import json, math, sys, itertools

def sub(a,b): return (a[0]-b[0], a[1]-b[1])
def add(a,b): return (a[0]+b[0], a[1]+b[1])
def mul(a,k): return (a[0]*k, a[1]*k)
def dot(a,b): return a[0]*b[0]+a[1]*b[1]
def cross(a,b): return a[0]*b[1]-a[1]*b[0]
def left(d): return (-d[1], d[0])
def ln(v): return math.sqrt(v[0]*v[0]+v[1]*v[1])
def hy(v): return math.hypot(v[0], v[1])

def units(v):
    l = ln(v); h = hy(v)
    return {'rec': (v[0]*(1.0/l), v[1]*(1.0/l)), 'div': (v[0]/l, v[1]/l), 'hdiv': (v[0]/h, v[1]/h), 'hrec': (v[0]*(1.0/h), v[1]*(1.0/h))}

def meets(P, D, Q, E):
    """Several ways to intersect line P + sD with Q + tE; yields (name, point)."""
    den = cross(D, E)
    s = cross(sub(Q, P), E) / den
    yield 'pd', add(P, mul(D, s))
    t = cross(sub(Q, P), D) / den
    yield 'qe', add(Q, mul(E, t))
    # determinant form with two points per line
    x1, y1 = P; x2, y2 = add(P, D); x3, y3 = Q; x4, y4 = add(Q, E)
    dd = (x1 - x2) * (y3 - y4) - (y1 - y2) * (x3 - x4)
    a = x1 * y2 - y1 * x2; b = x3 * y4 - y3 * x4
    yield 'det', ((a * (x3 - x4) - (x1 - x2) * b) / dd, (a * (y3 - y4) - (y1 - y2) * b) / dd)

def corner_measures(a0, p, b1, t, off):
    """Yields (name, value) for A's face at offset off (left +) meeting B's face at the same offset."""
    vA = sub(p, a0); vB = sub(b1, p)
    for un in ('rec', 'div', 'hdiv'):
        dA = units(vA)[un]; dB = units(vB)[un]
        nA = left(dA); nB = left(dB)
        uA = mul(dA, -1.0)
        free = add(p, mul(nA, off))
        bases = {
            'A0B0': (add(a0, mul(nA, off)), add(p, mul(nB, off))),
            'ApBp': (add(p, mul(nA, off)), add(p, mul(nB, off))),
            'A0B1': (add(a0, mul(nA, off)), add(b1, mul(nB, off))),
            'ApB1': (add(p, mul(nA, off)), add(b1, mul(nB, off))),
        }
        for bn, (PA, PB) in bases.items():
            for dn, (D, E) in {'unit': (dA, dB), 'full': (vA, vB)}.items():
                for mn, x in meets(PA, D, PB, E):
                    nm = '%s/%s/%s/%s' % (un, bn, dn, mn)
                    yield nm + '/along', abs(dot(sub(x, p), uA))
                    yield nm + '/alongd', abs(dot(sub(x, p), dA))
                    yield nm + '/free', ln(sub(x, free))
                    yield nm + '/freeh', hy(sub(x, free))
                    yield nm + '/alfree', abs(dot(sub(x, free), dA))
                    # along the centre line from its start, minus its length
                    yield nm + '/cl', abs(dot(sub(x, a0), dA) - ln(vA))

rows = []
for f in sys.argv[1:]:
    for l in open(f):
        if l.startswith('{'):
            rows.append(json.loads(l))
score = {}
for r in rows:
    a0, p, b1, t = tuple(r['a0']), tuple(r['p']), tuple(r['b1']), r['t']
    for side, off in (('L', t / 2), ('R', -t / 2)):
        want = r[side]
        for nm, v in corner_measures(a0, p, b1, t, off):
            for cmp in ('le', 'lt'):
                ok = (v <= t) if cmp == 'le' else (v < t)
                k = nm + '/' + cmp
                score.setdefault(k, 0)
                if ok == want:
                    score[k] += 1
best = sorted(score.items(), key=lambda kv: -kv[1])
print(len(rows) * 2, 'corners')
for k, v in best[:25]:
    print(v, k)

