    let mut out: Vec<(u64, f64)> = Vec::new();
    for k in 0..n {
        let delta = target[k] - pos[k];
        let Some(x) = el[k] else { continue };
        match out.iter().find(|(y, _)| *y == x) {
            Some((_, dd)) => {
                if (dd - delta).abs() > TOL {
                    return Err(apart());
                }
            }
            None => out.push((x, delta)),
        }
    }
    Ok(out
        .into_iter()
        .filter(|(_, dd)| dd.abs() > TOL)
        .map(|(x, dd)| (x, [laid.dir[0] * dd, laid.dir[1] * dd]))
        .collect())
}

