"""search.py data.json...: which way of computing stations reproduces the original's values."""
import json, math, sys, itertools
from fractions import Fraction as Fr

def fma(a, b, c): return float(Fr(a) * Fr(b) + Fr(c))
def sub(a, b): return (a[0] - b[0], a[1] - b[1])
def add(a, b): return (a[0] + b[0], a[1] + b[1])
def mul(a, k): return (a[0] * k, a[1] * k)
def dot(a, b): return a[0] * b[0] + a[1] * b[1]
def dotf(a, b): return fma(a[0], b[0], a[1] * b[1])
def dotf2(a, b): return fma(a[1], b[1], a[0] * b[0])
def cross(a, b): return a[0] * b[1] - a[1] * b[0]
def crossf(a, b): return fma(a[0], b[1], -(a[1] * b[0]))
def left(d): return (-d[1], d[0])
def east(d):
    if d[0] > 1e-9 or (abs(d[0]) <= 1e-9 and d[1] > 0): return d
    return (-d[0], -d[1])

def unit_rec(v):
    l = math.sqrt(v[0] * v[0] + v[1] * v[1]); k = 1.0 / l
    return (v[0] * k, v[1] * k)
def unit_div(v):
    l = math.sqrt(v[0] * v[0] + v[1] * v[1])
    return (v[0] / l, v[1] / l)
def unit_hyp(v):
    l = math.hypot(v[0], v[1])
    return (v[0] / l, v[1] / l)
UNITS = {'rec': unit_rec, 'div': unit_div, 'hyp': unit_hyp}

def line_station(var, a, b, at, dr, D, C):
    u = sub(b, a)
    if var == 'X1':
        t = C(sub(a, at), u) / C(dr, u)
        return D(sub(add(at, mul(dr, t)), at), dr)
    if var == 't1':
        return C(sub(a, at), u) / C(dr, u)
    if var == 'X3':
        uu = unit_rec(u)
        t = C(sub(a, at), uu) / C(dr, uu)
        return D(sub(add(at, mul(dr, t)), at), dr)
    if var == 'X4':
        t = C(sub(at, a), dr) / C(u, dr)
        return D(sub(add(a, mul(u, t)), at), dr)
    if var == 'Xa':
        return D(sub(a, at), dr)
    if var == 'Xb':
        return D(sub(b, at), dr)
    if var == 'F':
        uu = unit_rec(u)
        f = add(a, mul(uu, D(sub(at, a), uu)))
        return D(sub(f, at), dr)
    if var == 'Fu':
        f = add(a, mul(u, D(sub(at, a), u) / D(u, u)))
        return D(sub(f, at), dr)
    if var == 'abs1':
        t = C(sub(a, at), u) / C(dr, u)
        x = add(at, mul(dr, t))
        return D(x, dr)
    raise KeyError(var)

def point_station(var, p, at, dr, D):
    if var == 'P1':
        return D(sub(p, at), dr)
    if var == 'P2':
        return D(p, dr) - D(at, dr)
    if var == 'Pabs':
        return D(p, dr)
    raise KeyError(var)

def run(data, dirv, lnv, ptv, dv, cv):
    D = {'dot': dot, 'dotf': dotf, 'dotf2': dotf2}[dv]
    C = {'cross': cross, 'crossf': crossf}[cv]
    unit = UNITS[dirv]
    G = {int(k): (tuple(v[0]), tuple(v[1])) for k, v in data['grids'].items()}
    ok = 0
    for dm in data['dims']:
        at = tuple(dm['at'])
        geos = []
        for r in dm['refs']:
            g = G[r['id']]
            if 'point' in r:
                geos.append(('p', g[0] if r['point'] == 'start' else g[1]))
            else:
                geos.append(('l', g))
        lines = [g for k, g in geos if k == 'l']
        if lines:
            a, b = lines[0]
            dr = east(left(unit(sub(b, a))))
        else:
            p0 = geos[0][1]
            nxt = [g for k, g in geos[1:] if math.dist(g, p0) > 1e-9]
            if not nxt:
                continue
            dr = east(unit(sub(nxt[0], p0)))
        st = []
        for k, g in geos:
            if k == 'p':
                st.append(point_station(ptv, g, at, dr, D))
            else:
                st.append(line_station(lnv, g[0], g[1], at, dr, D, C))
        st.sort()
        vals = [repr(st[i + 1] - st[i]) for i in range(len(st) - 1)]
        if vals == dm['values']:
            ok += 1
    return ok

data = {'grids': {}, 'dims': []}
for f in sys.argv[1:]:
    d = json.load(open(f))
    off = len(data['grids']) * 1000
    # keep files apart: their grid ids collide
    data = d if not data['dims'] else data
results = []
for dirv in UNITS:
    for lnv in ('X1', 't1', 'X3', 'X4', 'Xa', 'Xb', 'F', 'Fu', 'abs1'):
        for ptv in ('P1', 'P2', 'Pabs'):
            for dv in ('dot', 'dotf', 'dotf2'):
                for cv in ('cross', 'crossf'):
                    results.append((run(data, dirv, lnv, ptv, dv, cv), dirv, lnv, ptv, dv, cv))
results.sort(reverse=True)
print(len(data['dims']))
for r in results[:12]:
    print(r)
# by kind for the best

